catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        g_form.setMandatory('related_admission', true);
        g_form.setReadOnly('requested_for', true);
        g_form.setReadOnly('hospital', true);
        g_form.setReadOnly('contact_name', true);
        g_form.setReadOnly('contact_phone', true);
        return;
    }


    if (newValue) { // related admission selected 
        //make appointment visible = false 
        g_form.setMandatory('related_appointment', false);
        g_form.setDisplay('related_appointment', false);

        if (requested_for) {
            g_form.setReadOnly('requested_for', true);
        }
        if (hospital) {
            g_form.setReadOnly('hospital', true);
        }
        if (contact_name) {
            g_form.setReadOnly('contact_name', true);
        }
        if (contact_phone) {
            g_form.setReadOnly('contact_phone', true);
        }
    } else if (newValue == '') { // wapas se empty kr diya
        g_form.setMandatory('related_appointment', true);
        g_form.setDisplay('related_appointment', true);
    }




}
